//! 🌱️ Reference-only parents encode no payload while typed authored birth custody retains its original owner.
use super::*;
#[test]fn reference_only_members_keep_original_birth_payload_separate(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🌱️birth/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let target=&row["member"]["handle"]["target"];let member=LayoutDrawingMember{handle:store::os_store::artifact_child::ArtifactChild::new(row["member"]["handle"]["childId"].as_str().unwrap().to_string(),semio_framework_artifact_reference::ArtifactRef{artifact_id:target["artifactId"].as_str().unwrap().into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.draw.drawing".into(),standard:"1".into(),subset:"*".into()}})};let encoded:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(&member.to_value())).unwrap();assert_eq!(encoded,row["member"]);assert!(encoded.get("content").is_none());let mut inline=encoded.clone();inline["content"]=row["initial"].clone();assert!(LayoutDrawingMember::from_value(semio_framework_value::DslValue::from(inline)).is_err());let source=if row["source"]["kind"]=="document"{LayoutDrawingBirthSource::Document}else{LayoutDrawingBirthSource::Page{page_id:row["source"]["pageId"].as_str().unwrap().into()}};let wire:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(&source.to_value())).unwrap();assert_eq!(wire,row["source"]);let original=String::from("genuine original payload");let pointer=original.as_ptr();let birth=LayoutDrawingBirth{source,member,initial:original};assert_eq!(birth.initial.as_ptr(),pointer);}}
